import zipfile, json, re
from xml.etree import ElementTree as ET

TEMPLATE='/root/event_announcement_template.hwpx'
DATA='/root/event_data.json'
OUT='/root/event_announcement_ready.hwpx'

mapping=json.load(open(DATA,'r',encoding='utf-8'))
# Build placeholder->value mapping
ph_map={f'{{{{{k}}}}}': str(v) for k,v in mapping.items()}


def replace_in_text(text):
    replaced=False
    counts={}
    for ph,val in ph_map.items():
        if ph in text:
            c=text.count(ph)
            text=text.replace(ph,val)
            replaced=True
            counts[ph]=c
    return text, replaced, counts


def strip_linesegarray_in_modified_paragraphs(xml_text):
    # Parse while preserving namespace-qualified tags.
    root=ET.fromstring(xml_text)

    def local(tag):
        return tag.rsplit('}',1)[-1] if '}' in tag else tag

    modified_p_ids=set()
    # Iterate paragraphs (hp:p) by local-name
    for p in root.iter():
        if local(p.tag) != 'p':
            continue
        # Gather all text under paragraph
        full=''.join([t.text or '' for t in p.iter() if local(t.tag)=='t'])
        if '{{' in full and '}}' in full:
            # still has placeholders (shouldn't happen post replacement) but treat as modified candidate
            pass
        # Determine if paragraph has any placeholder occurrences
        if any(ph in full for ph in ph_map.keys()):
            # will be modified by replacement
            pid=p.attrib.get('id')
            if pid is not None:
                modified_p_ids.add(pid)

    # Now perform replacements in all hp:t nodes and mark modified paragraphs robustly
    modified_elements=[]
    for p in root.iter():
        if local(p.tag)!='p':
            continue
        p_modified=False
        for t in p.iter():
            if local(t.tag)!='t':
                continue
            if t.text:
                new_text, rep, _ = replace_in_text(t.text)
                if rep:
                    t.text=new_text
                    p_modified=True
        if p_modified:
            modified_elements.append(p)

    # Remove linesegarray under modified paragraphs
    removed=0
    for p in modified_elements:
        # Need parent mapping for removals; ElementTree lacks getparent, so walk with stack
        pass

    # Build parent map
    parent={c:par for par in root.iter() for c in par}
    for p in modified_elements:
        # collect any descendant linesegarray elements
        for el in list(p.iter()):
            if local(el.tag)=='linesegarray':
                par=parent.get(el)
                if par is not None:
                    par.remove(el)
                    removed+=1
    return ET.tostring(root, encoding='utf-8', xml_declaration=True).decode('utf-8'), removed, len(modified_elements)


repl_summary={}
warn_placeholders=set()

with zipfile.ZipFile(TEMPLATE,'r') as zin, zipfile.ZipFile(OUT,'w',compression=zipfile.ZIP_DEFLATED) as zout:
    for info in zin.infolist():
        data=zin.read(info.filename)
        name=info.filename
        if name.lower().endswith('.xml'):
            text=data.decode('utf-8')

            # Detect placeholders present before replacement
            found=set(re.findall(r'\{\{[^}]+\}\}', text))
            for ph in found:
                if ph not in ph_map:
                    warn_placeholders.add(ph)

            # Parse, replace, and strip linesegarray in modified paragraphs
            new_text, removed, modified_p_count = strip_linesegarray_in_modified_paragraphs(text)

            # Count replacements (after)
            counts={}
            for ph,val in ph_map.items():
                # count how many times replacement value appears? unreliable; instead count occurrences in original
                c=text.count(ph)
                if c:
                    counts[ph]=c
            if counts:
                repl_summary[name]={'replacements':counts,'modified_paragraphs':modified_p_count,'linesegarray_removed':removed}

            zout.writestr(name, new_text.encode('utf-8'))
        else:
            # copy unchanged
            zout.writestr(name, data)

if warn_placeholders:
    print('WARNING: placeholders in template missing from JSON:', sorted(warn_placeholders))

print('Wrote', OUT)
print('Replacement summary:')
for f,meta in repl_summary.items():
    print('-', f)
    for ph,c in sorted(meta['replacements'].items()):
        print(f'    {ph}: {c}')
    print('    modified_paragraphs:', meta['modified_paragraphs'])
    print('    linesegarray_removed:', meta['linesegarray_removed'])

