        if local(p.tag)!='p':
            continue
        pid=p.attrib.get('id')
        if pid in ids_modified:
            if any(local(e.tag)=='linesegarray' for e in p.iter()):
                raise SystemExit(f'linesegarray still present in modified paragraph id={pid}')
    print('linesegarray removed from modified paragraphs: OK')

    # spot-check Korean labels still present
    for needle in ['행사 공지문','행사명:','일시:','장소:','주관부서:','대상:','참가비:','신청 마감:','문의처:','상세 내용:','주의사항:','비고: 사전 신청 필수']:
        if needle not in sec:
            print('MISSING LABEL?', needle)
    print('spot-check labels: done')

